# Load grids to track what we've seen
import os, re

def load():
    d = os.environ.get('RLM_SESSION_DIR', '')
    if not d:
        return {}
    try:
        # Try different paths for the session file
        base = os.path.basename(d)
        paths = [
            os.path.normpath(os.path.join(d, '..', 'sessions', base + '.jsonl')),
            os.path.normpath(os.path.join(d, '../../sessions/' + base + '.jsonl')),
        ]
        for p in paths:
            if os.path.exists(p):
                G = {}
                content = open(p).read()
                for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
                    k, h, w = m[1], int(m[2]), int(m[3])
                    rows = [r.split() for r in content[m.end():].split('\n')[:h]]
                    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
                        G[k] = [[int(x) for x in r] for r in rows]
                return G
    except:
        pass
    return {}

G = load()
print("Loaded keys:", sorted(G.keys()))
for k, v in G.items():
    print(f"{k}: {v}")

