# Test hypothesis: B fills with reversed index logic

S_A_demo = [1,2,4,3]
S_B_demo = [5,7,8,6]

def classify(val):
    return "A" if val in S_A_demo else ("B" if val in S_B_demo else None)

def get_idx_for_group(val, group):
    if group == "A":
        return S_A_demo.index(val)
    else:
        # For B, count from the end
        idx = len(S_B_demo) - 1 - S_B_demo.index(val)
        return idx

def apply_fill(input_row, result_row=None):
    if result_row is None:
        result_row = list(input_row)

    row_indep = result_row.copy()

    for col in range(len(row_indep)):
        if row_indep[col] != 0:
            has_neighbor = any(row_indep[col+dc] != 0 for dc in [-1, 1] if 0 <= col+dc < len(row_indep))
            if has_neighbor:
                continue

            val = row_indep[col]
            grp = classify(val)

            if grp is None:
                continue

            seq = S_A_demo if grp == "A" else S_B_demo
            idx = get_idx_for_group(val, grp)
            start_col = max(0, col - idx)
            end_col = start_col + len(seq)

            for c in range(start_col, min(end_col, len(result_row))):
                result_row[c] = seq[c - start_col]

    return result_row

